setups.snippet:
{
  "mcpServers": {
    "polarion": {
      "command": "npx",
      "args": ["-y", "polarion-mcp"],
      "env": {
        "API_BASE_URL": "https://YOUR-POLARION/polarion/rest/v1",
        "BEARER_TOKEN": "YOUR_POLARION_PAT"
      }
    }
  }
}

{
  "servers": {
    "polarion": {
      "type": "stdio",
      "command": "npx",
      "args": ["-y", "polarion-mcp"],
      "env": {
        "API_BASE_URL": "https://YOUR-POLARION/polarion/rest/v1",
        "BEARER_TOKEN": "YOUR_POLARION_PAT"
      }
    }
  }
}

{
  "mcp_servers": [
    {
      "type": "url",
      "name": "polarion",
      "url": "https://YOUR-SERVER/mcp",
      "authorization_token": "YOUR_POLARION_PAT"
    }
  ],
  "tools": [
    {
      "type": "mcp_toolset",
      "mcp_server_name": "polarion"
    }
  ]
}

{
  "tools": [
    {
      "type": "mcp",
      "server_label": "polarion",
      "server_url": "https://YOUR-SERVER/mcp",
      "authorization": "YOUR_POLARION_PAT",
      "require_approval": "always"
    }
  ]
}

{
  "mcpServers": {
    "polarion": {
      "command": "npx",
      "args": [
        "-y",
        "polarion-mcp"
      ],
      "env": {
        "API_BASE_URL": "https://YOUR-POLARION/polarion/rest/v1",
        "BEARER_TOKEN": "YOUR_POLARION_PAT"
      }
    }
  }
}

{
  "mcpServers": {
    "polarion": {
      "serverUrl": "https://YOUR-SERVER/mcp",
      "headers": {
        "Authorization": "Bearer YOUR_POLARION_PAT"
      }
    }
  }
}

server.snippet:
curl https://api.anthropic.com/v1/messages \
  -H "Content-Type: application/json" \
  -H "X-API-Key: $ANTHROPIC_API_KEY" \
  -H "anthropic-version: 2023-06-01" \
  -H "anthropic-beta: mcp-client-2025-11-20" \
  -d '{
    "model": "YOUR_CLAUDE_MODEL",
    "max_tokens": 1000,
    "messages": [{"role": "user", "content": "Which Polarion user am I? Use getCurrentUser."}],
    "mcp_servers": [
      {
        "type": "url",
        "name": "polarion",
        "url": "https://YOUR-SERVER/mcp",
        "authorization_token": "YOUR_POLARION_PAT"
      }
    ],
    "tools": [
      {"type": "mcp_toolset", "mcp_server_name": "polarion"}
    ]
  }'
